import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-04-18","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-04-18","date":"2022-04-18T00:00:00.000Z","updated":"2022-04-22T00:00:00.000Z","tags":["Ceph","分布式存储","配置文件","镜像选择算法","镜像版本"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-04-18.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-04-18.md","lastUpdated":1780460162000}'),a={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-04-18.md"};function o(s,l,n,h,p,d){return t(),i("div",null,[...l[0]||(l[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次Ceph Orchestrator会议由于参与人数较少，原计划讨论的问题优先级排序被推迟。会议主要讨论了两个相关议题，并计划在后续会议中继续讨论。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>配置文件的使用</strong></p><ul><li><strong>讨论内容</strong>：讨论了当前使用的配置文件（如 <code>etcsef.com</code>）的重要性。由于大多数守护进程（demons）从监视器（monitor）获取配置信息，因此对于配置文件的需求进行了质疑。</li><li><strong>主要观点</strong>： <ul><li>配置文件目前主要用于获取监视器的IP地址，以便执行shell命令。</li><li>在容器化环境中，配置文件的重要性有所降低，因为容器通常会挂载自己的配置文件。</li><li>长期来看，如果集群配置可以在其他地方（如 <code>bar leap</code>）获取，配置文件可能变得不再必要。</li></ul></li><li><strong>决定事项</strong>： <ul><li>短期内不会移除配置文件，因为可能存在一些遗留系统依赖它。</li><li>需要进一步调查和测试，以确定是否可以完全移除配置文件。</li></ul></li></ul></li><li><p><strong>镜像选择算法</strong></p><ul><li><strong>讨论内容</strong>：讨论了在升级过程中，如何选择合适的镜像（image）。当前算法仅选择最新镜像，但在混合旧镜像和新镜像的环境中可能不适用。</li><li><strong>主要观点</strong>： <ul><li>建议使用守护进程（demons）的信息来选择镜像，如果无法获取则回退到旧算法。</li><li>可以通过优先级列表来选择镜像，优先考虑用户指定的镜像，然后是守护进程的配置，最后是默认的最新镜像。</li></ul></li><li><strong>决定事项</strong>： <ul><li>需要实现新的镜像选择算法，并进行充分的测试。</li><li>需要添加更多的日志信息，以便用户了解正在使用的镜像。</li></ul></li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><p><strong>配置文件的使用</strong>：</p><ul><li>继续调查和测试配置文件的使用情况。</li><li>考虑长期移除配置文件的可能性，并制定相应的计划。</li></ul></li><li><p><strong>镜像选择算法</strong>：</p><ul><li>实现新的镜像选择算法。</li><li>添加更多的日志信息，以便用户了解正在使用的镜像。</li><li>进行充分的测试，确保新算法在各种情况下都能正常工作。</li></ul></li><li><p><strong>其他事项</strong>：</p><ul><li>将未讨论的议题推迟到下一次会议。</li><li>与Mike进一步讨论关于二进制文件重构的计划和策略。</li></ul></li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在讨论完所有议题后结束，计划在下次会议中继续讨论未完成的事项。</p>',9)])])}const _=e(a,[["render",o]]);export{u as __pageData,_ as default};
